  "MOD_APPLY_DOOR_FINISH": {
    "module_id": "MOD_APPLY_DOOR_FINISH",
    "name": "Apply Door Finish Coat",
    "phase": "finish",
    "intent": "One coat of finish per module invocation. Spray and brush tasks both present, gated by application_method so only the relevant one fires. Scenarios needing two coats list this module twice with MOD_INTERSTAGE_DOOR between them.",
    "tasks": [
      {
        "task_id": "TSK_DOOR_FINISH_SPRAY",
        "name": "Spray Door Finish",
        "ps_key": "PS_SURFACE_EA_SIDE.DOOR_SLAB",
        "uom": "EA_SIDE",
        "skill_level": "experienced",
        "rate_per_hour": 10,
        "applies_when": {
          "application_method": [
            "spray"
          ]
        }
      },
      {
        "task_id": "TSK_DOOR_FINISH_BRUSH",
        "name": "Brush Door Finish",
        "ps_key": "PS_SURFACE_EA_SIDE.DOOR_SLAB",
        "uom": "EA_SIDE",
        "skill_level": "experienced",
        "rate_per_hour": 4,
        "applies_when": {
          "application_method": [
            "brush"
          ]
        }
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": false,
      "texture": false,
      "complexity": true
    },
    "doctrine": "Spray (10 sides/hr) is 2.5x faster than brush (4 sides/hr) for door finish. Brush is the labor-intensive premium method that produces brush marks the customer often wants on traditional residential doors. Spray produces a glass-smooth laydown with no brush marks. Source spec uses identical rates for coat 1 and coat 2 — no rates_by_coat needed. Door type complexity comes from the door_type modifier in the existing engine's DOOR_TYPE_MODIFIERS table; for Phase 1b minimal validation we test with uniform door types so the modifier is constant."
  },
  "MOD_APPLY_DOOR_FRAME_FINISH_BRUSH": {
    "module_id": "MOD_APPLY_DOOR_FRAME_FINISH_BRUSH",
    "name": "Apply Door Frame Finish (Brush Method)",
    "phase": "apply",
    "intent": "Brush finish coat onto primed door frame. One coat per module invocation. Scenarios needing two coats list this module twice with interstage between. Brush preserves the traditional residential finish look — brush marks are acceptable and expected.",
    "tasks": [
      {
        "task_id": "TSK_DOOR_FRAME_BRUSH_FINISH",
        "name": "Brush Door Frame Finish Coat",
        "ps_key": "PS_SURFACE_EA.DOOR_FRAME_SET",
        "uom": "EA",
        "skill_level": "experienced",
        "rates_by_coat": {
          "1": 4,
          "2": 5
        }
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": false,
      "complexity": true
    },
    "doctrine": "Coat 1 at 4 frames/hr (15 min each) is slower than coat 2 at 5 frames/hr (12 min each) — same pattern as trim brush finish (80 LF/hr → 90 LF/hr). Frame painting involves working all six surfaces (two jamb faces, head jamb face, stop molding, door-facing edges). Spray rates roughly 4x these in MOD_APPLY_DOOR_FRAME_FINISH_SPRAY."
  },
  "MOD_APPLY_DOOR_FRAME_FINISH_SPRAY": {
    "module_id": "MOD_APPLY_DOOR_FRAME_FINISH_SPRAY",
    "name": "Apply Door Frame Finish (Spray Method)",
    "phase": "apply",
    "intent": "Airless spray finish coat onto primed door frame. One coat per module invocation. Spray produces a glass-smooth laydown — the premium finish look expected at QT4/QT5. Requires wall masking and fixture covers from the setup module.",
    "tasks": [
      {
        "task_id": "TSK_DOOR_FRAME_SPRAY_FINISH",
        "name": "Spray Door Frame Finish Coat",
        "ps_key": "PS_SURFACE_EA.DOOR_FRAME_SET",
        "uom": "EA",
        "skill_level": "experienced",
        "rates_by_coat": {
          "1": 15,
          "2": 18
        }
      }
    ],
    "modifier_eligibility": {
      "qt": true,
      "height": true,
      "texture": false,
      "complexity": true
    },
    "doctrine": "Spray rates ~4x brush rates, matching trim ratio (trim brush 80-90 LF/hr vs spray 380-445 LF/hr = ~5x; frames slightly less because each frame still needs careful trigger control around door opening). Coat 2 faster than coat 1 — same wet-in-wet advantage as trim spray."
  },
