  "MOD_INTERSTAGE_SAND": {
    "module_id": "MOD_INTERSTAGE_SAND",
    "name": "Light Sand Between Finish Coats",
    "phase": "interstage",
    "intent": "Light fine-grit sand of cured first finish coat to flatten any nibs, brush marks, or laydown imperfections before the second finish coat. Always followed by vacuum dust. QT4 and QT5 only — lower tiers don't sand between coats.",
    "tasks": [
      {
        "task_id": "TSK_LIGHT_SAND_BETWEEN_COATS_WALL",
        "name": "Light Sand Between Finish Coats",
        "ps_key": "PS_SURFACE_SF.WALL_FIELD",
        "uom": "SF",
        "skill_level": "general",
        "rates_by_tier": {
          "QT4": 600,
          "QT5": 420
        }
      },
      {
        "task_id": "TSK_VACUUM_INTERCOAT_DUST_WALL",
        "name": "Vacuum Intercoat Sanding Dust",
        "ps_key": "PS_SURFACE_SF.WALL_FIELD",
        "uom": "SF",
        "skill_level": "general",
        "rates_by_tier": {
          "QT4": 750,
          "QT5": 750
        }
      }
    ],
    "modifier_eligibility": {
      "qt": false,
      "height": true,
      "texture": false,
      "complexity": true
    },
    "doctrine": "Interstage sanding uses a finer grit than first-pass primer sanding (320+ at QT5, 220-320 at QT4) and slows accordingly. Cannot be skipped at QT4/QT5 — the second coat needs a clean key to bond uniformly and the sanded surface eliminates any first-coat texture artifacts. Vacuum is mandatory before the second spray pass."
  },
  "MOD_INTERSTAGE_SAND_CEILING": {
    "module_id": "MOD_INTERSTAGE_SAND_CEILING",
    "name": "Light Sand Between Ceiling Finish Coats",
    "phase": "interstage",
    "intent": "Light fine-grit sand of cured first ceiling finish coat to flatten any nibs or laydown imperfections before second coat. Always followed by vacuum dust. QT4 and QT5 only. Sand rate varies by application method because spray-applied film has less laydown texture than rolled film.",
    "tasks": [
      {
        "task_id": "TSK_LIGHT_SAND_BETWEEN_COATS_CEILING",
        "name": "Light Sand Between Ceiling Coats",
        "ps_key": "PS_SURFACE_SF.CEILING_FIELD",
        "uom": "SF",
        "skill_level": "general",
        "rates": [
          {
            "rate_per_hour": 500,
            "applies_when": {
              "quality_tier": [
                "QT4"
              ]
            }
          },
          {
            "rate_per_hour": 350,
            "applies_when": {
              "quality_tier": [
                "QT5"
              ],
              "application_method": [
                "roll"
              ]
            }
          },
          {
            "rate_per_hour": 500,
            "applies_when": {
              "quality_tier": [
                "QT5"
              ],
              "application_method": [
                "spray_backroll"
              ]
            }
          }
        ]
      },
      {
        "task_id": "TSK_VACUUM_INTERCOAT_DUST_CEILING",
        "name": "Vacuum Intercoat Sanding Dust",
        "ps_key": "PS_SURFACE_SF.CEILING_FIELD",
        "uom": "SF",
        "skill_level": "general",
        "rate_per_hour": 600
      }
    ],
    "modifier_eligibility": {
      "qt": false,
      "height": true,
      "texture": false,
      "complexity": true
    },
    "doctrine": "Roll-applied first coat has visible laydown texture that requires more sanding at QT5 (350 SF/hr) than spray-applied first coat (500 SF/hr at QT5) because the spray film is already smoother. At QT4 the difference disappears — both methods sand at 500 SF/hr because the QT4 inspection threshold doesn't reward extra sanding effort."
  },
